SELECT c.user_id, u.name, u.gender, u.birth_date, c.level, c.hourly_rate, c.photo_url, c.awards FROM coach c JOIN user u ON c.user_id = u.id WHERE c.deleted = 0 AND u.deleted = 0 AND u.campus_id = #{queryDTO.campusId}
AND c.is_approved = #{queryDTO.isApproved}
AND u.name LIKE CONCAT('%', #{queryDTO.name}, '%')
AND u.gender = #{queryDTO.gender}
AND c.level = #{queryDTO.level}
ORDER BY c.create_time DESC LIMIT #{offset}, #{limit}

SELECT COUNT(1)
FROM coach c
JOIN user u ON c.user_id = u.id
WHERE c.deleted = 0
AND u.deleted = 0
AND u.campus_id = #{queryDTO.campusId}

    AND c.is_approved = #{queryDTO.isApproved}


    AND u.name LIKE CONCAT('%', #{queryDTO.name}, '%')


    AND u.gender = #{queryDTO.gender}


    AND c.level = #{queryDTO.level}
